#include <bits/stdc++.h>using namespace std;#define int long long#define double long double void solve() {    int n;    cin >> n;    vector<int> v(n);    for (int i = 0; i < n; i++) {        cin >> v[i];    }     int total_distance = 0;    for (int i = 0; i < n - 1; i++) {        total_distance += abs(v[i] - v[i + 1]);    }     int current_reduction = 0, max_reduction = 0;    for (int i = 0; i < n; i++) {        if (i == 0) {            current_reduction = abs(v[1] - v[0]);        } else if (i == n - 1) {            current_reduction = abs(v[n - 2] - v[n - 1]);        } else {            current_reduction = abs(v[i] - v[i - 1]) + abs(v[i + 1] - v[i]) -                                abs(v[i + 1] - v[i - 1]);        }        max_reduction = max(current_reduction, max_reduction);    }    cout << total_distance - max_reduction << "\n";} int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int t;    cin >> t;    for (int i = 0; i < t; i++) {        solve();    }}